  function assertFile(file,{kind='file',types=[],extensions=[],maxSize=50*1024*1024}={}){
    if(!file)throw new Error('Selecione um arquivo.');
    if(file.size<=0)throw new Error('Arquivo vazio.');
    if(file.size>maxSize)throw new Error(`Arquivo acima do limite de ${Math.round(maxSize/1024/1024)}MB.`);
    const name=String(file.name||'').toLowerCase(),ext=name.includes('.')?name.split('.').pop():'';
    if(extensions.length&&!extensions.includes(ext))throw new Error(`Extensão inválida para ${kind}.`);
    if(types.length&&file.type&&!types.includes(file.type))throw new Error(`Tipo MIME inválido para ${kind}.`);
    if(types.includes('application/pdf')&&ext!=='pdf')throw new Error('PDF oficial precisa ter extensão .pdf.');
    return ext;
  }
  async function uploadToLessonStorage(path,file){
    const client=storageClient();
    if(!client?.storage?.from)throw new Error('Supabase Storage indisponível nesta sessão.');
    const bucket=client.storage.from(storageBucket());
    const {error}=await bucket.upload(path,file,{cacheControl:'3600',upsert:true,contentType:file.type||undefined});
    if(error)throw error;
    const signed=await bucket.createSignedUrl(path,60*60*6);
    if(!signed?.data?.signedUrl)throw new Error('Upload concluído, mas link seguro não foi gerado.');
    return signed.data.signedUrl;
  }
  async function signedStorageUrl(path,expiresIn=60*60*6){
    if(!path)return '';
    const client=storageClient();
    if(!client?.storage?.from)throw new Error('Supabase Storage indisponível nesta sessão.');
    const {data,error}=await client.storage.from(storageBucket()).createSignedUrl(path,expiresIn);
    if(error)throw error;
    return data?.signedUrl||'';
  }
