  function syncPurpleWayMioloUnits(workspace){
    const catalog=purpleWayMioloCatalog();
    for(const [courseId,units] of Object.entries(catalog)){
      const course=(workspace.courses||[]).find(item=>item.id===courseId);
      if(!course)continue;
      const existing=course.units||[];
      const known=new Set(units.map(unit=>unit.id));
      const merged=units.map(unit=>{
        const current=existing.find(item=>item.id===unit.id);
        return {...(current||{}),...unit,basePdf:current?.basePdf||unit.basePdf||null,lessons:current?.lessons||unit.lessons||[],createdAt:current?.createdAt||unit.createdAt||'',updatedAt:current?.updatedAt||unit.updatedAt||''};
      });
      const extras=existing.filter(unit=>!known.has(unit.id));
      course.units=[...merged,...extras].sort((a,b)=>Number(a.order||999)-Number(b.order||999));
      course.status='active';
      if(courseId==='change'||courseId==='inspire')course.description=course.description?.includes('preparado para receber')?`${course.name} estruturado automaticamente a partir do miolo oficial para receber os planos padrão de unidade.`:course.description;
    }
    workspace.mioloCatalogVersion='purple-way-miolos-2026-09-18';
  }

