  function ensureWorkspace(){
    const db=getDb();
    if(!db.lessonPlansWorkspace||db.lessonPlansWorkspace.version<2)db.lessonPlansWorkspace=seedWorkspace();
    const workspace=db.lessonPlansWorkspace;
    workspace.version=4;
    workspace.ai=workspace.ai||{status:'unknown',lastError:'',updatedAt:''};
    workspace.collections=workspace.collections?.length?workspace.collections:[{id:'purple-way',name:'Purple Way',description:'Biblioteca pedagógica principal da Purple.',coverUrl:defaultCollectionCover('purple-way'),coverStoragePath:'',coverPositionX:50,coverPositionY:50,coverZoom:100,order:1,status:'active',bookIds:(workspace.courses||[]).map(course=>course.id)}];
    workspace.courses=workspace.courses||[];
    if(!workspace.collections.some(collection=>collection.id==='super-kids'))workspace.collections.push({id:'super-kids',name:'Super Kids',description:'Coleção infantil da Purple para organizar livros, unidades, planos e recursos do programa Super Kids.',coverUrl:'',coverStoragePath:'',coverPositionX:50,coverPositionY:50,coverZoom:100,order:2,status:'active',bookIds:[]});
    const superKids=workspace.collections.find(collection=>collection.id==='super-kids');
    const superKidsBooks=[
      ['super-kids-starter','Super Kids Starter','Starter',1],
      ['super-kids-1','Super Kids 1','Kids 1',2],
      ['super-kids-2','Super Kids 2','Kids 2',3],
      ['super-kids-3','Super Kids 3','Kids 3',4],
      ['super-kids-4','Super Kids 4','Kids 4',5],
      ['super-kids-5','Super Kids 5','Kids 5',6],
      ['super-kids-6','Super Kids 6','Kids 6',7]
    ];
    for(const [id,name,level,order] of superKidsBooks){
      if(!workspace.courses.some(course=>course.id===id))workspace.courses.push({id,collectionId:'super-kids',name,description:'Programa Super Kids preparado para receber unidades, capas, PDFs e planos oficiais.',level,order,status:'draft',coverUrl:'',pdfUrl:'',coverStoragePath:'',pdfStoragePath:'',pedagogicalInfo:'Pré-cadastro do programa Super Kids. Revisar e completar com miolo, unidades e plano oficial.',units:[]});
    }
    if(superKids)superKids.bookIds=Array.from(new Set([...(superKids.bookIds||[]),...superKidsBooks.map(([id])=>id)]));
    workspace.courses.forEach((course,index)=>{
      Object.assign(course,{collectionId:course.collectionId||'purple-way',description:course.description||`${course.name} reúne unidades, planos e recursos Purple.`,level:course.level||'',order:Number(course.order||index+1),status:course.status||'active',coverUrl:course.coverUrl||'',pdfUrl:course.pdfUrl||'',coverStoragePath:course.coverStoragePath||'',pdfStoragePath:course.pdfStoragePath||'',pedagogicalInfo:course.pedagogicalInfo||course.description||'',coverPositionX:Number(course.coverPositionX??50),coverPositionY:Number(course.coverPositionY??50),coverZoom:Number(course.coverZoom??100)});
      if(!course.coverStoragePath&&!course.coverUrl&&defaultCourseCover(course.id))course.coverUrl=defaultCourseCover(course.id);
      (course.units||[]).forEach(unit=>{unit.content=unit.content||unit.theme||'';unit.subtitle=unit.subtitle||unit.objective||'';unit.basePdf=unit.basePdf||null});
    });
    for(const collection of workspace.collections){collection.bookIds=collection.bookIds?.length?collection.bookIds:workspace.courses.filter(course=>course.collectionId===collection.id).map(course=>course.id);collection.status=collection.status||'active';collection.order=Number(collection.order||1);collection.coverStoragePath=collection.coverStoragePath||'';if(!collection.coverStoragePath&&(!collection.coverUrl||legacyDefaultCollectionCovers(collection.id).includes(collection.coverUrl)))collection.coverUrl=defaultCollectionCover(collection.id);collection.coverPositionX=Number(collection.coverPositionX??50);collection.coverPositionY=Number(collection.coverPositionY??50);collection.coverZoom=Number(collection.coverZoom??100);}
    workspace.lessonPlans=workspace.lessonPlans||{};
    for(const course of workspace.courses)for(const unit of course.units||[])for(const lesson of unit.lessons||[])if(!workspace.lessonPlans[lesson.id])workspace.lessonPlans[lesson.id]=defaultPlan(lesson,unit,course);
    importConnectRealBatch(workspace);
    syncPurpleWayMioloUnits(workspace);
    for(const plan of Object.values(workspace.lessonPlans)){
      plan.revision=Number(plan.revision||1);plan.baseVersion=Boolean(plan.baseVersion||plan.planType==='Plano Base Purple'||plan.status==='PUBLICADA');plan.postClassFeedback=plan.postClassFeedback||[];plan.aiSuggestions=plan.aiSuggestions||[];plan.attachments=plan.attachments||[];plan.basePdf=plan.basePdf||null;plan.lessonTab=plan.lessonTab||'base';
      plan.resources=(plan.resources||[]).map(resource=>({id:resource.id||uid('res'),title:resource.title||resource.label||'Recurso',label:resource.label||resource.title||'Recurso',type:resource.type||'Link',category:resource.category||'',status:resource.status||'approved',source:resource.source||'purple',description:resource.description||'',whenToUse:resource.whenToUse||'',url:resource.url||resource.link||'',link:resource.link||resource.url||'',storagePath:resource.storagePath||'',fileName:resource.fileName||'',fileSize:resource.fileSize||0,uploadedAt:resource.uploadedAt||resource.createdAt||'',contributorId:resource.contributorId||'',contributorName:resource.contributorName||'',stageKey:resource.stageKey||'general'}));
      for(const stage of LESSON_STAGES){plan.stages[stage.key]=plan.stages[stage.key]||{};plan.stages[stage.key].studentBookPages=plan.stages[stage.key].studentBookPages||pagesFrom(plan.stages[stage.key].pages,'SB');plan.stages[stage.key].workbookPages=plan.stages[stage.key].workbookPages||pagesFrom(plan.stages[stage.key].pages,'WB');}
    }
    workspace.contributions=workspace.contributions||[];workspace.publishedFeed=workspace.publishedFeed||[];workspace.cycles=workspace.cycles||[];workspace.lastOpened=workspace.lastOpened||{courseId:'discover',unitId:'discover-u01',lessonId:'discover-u01-l01'};
    getState().lessonPlans=getState().lessonPlans||{view:'library',collectionId:'',courseId:'',unitId:'',lessonId:'',searchTerm:'',mode:'read',viewerPage:1,viewerZoom:100};
    return workspace;
  }

  function findCollection(id){const w=ensureWorkspace();return w.collections.find(item=>item.id===id)||w.collections[0]}
  function findCourse(id){const w=ensureWorkspace();return w.courses.find(item=>item.id===id)||w.courses[0]}
  function findUnit(courseId,unitId){const c=findCourse(courseId);return c?.units?.find(item=>item.id===unitId)||c?.units?.[0]}
  function findLessonMeta(lessonId){for(const course of ensureWorkspace().courses)for(const unit of course.units||[]){const lesson=(unit.lessons||[]).find(item=>item.id===lessonId);if(lesson)return {course,unit,lesson};}return {course:null,unit:null,lesson:null}}
  function findPlan(id){return ensureWorkspace().lessonPlans[id]||null}
  function findCycle(id){return ensureWorkspace().cycles.find(item=>item.id===id)||null}
  function collectionBooks(collection){const ids=new Set(collection.bookIds||[]);return ensureWorkspace().courses.filter(course=>course.collectionId===collection.id||ids.has(course.id)).sort((a,b)=>a.order-b.order)}
  function lessonCounts(unit){return (unit.lessons||[]).reduce((acc,lesson)=>{acc.total++;if(lesson.status==='PUBLICADA')acc.ready++;return acc},{total:0,ready:0})}
  function workflowLabel(status){return WORKFLOW_LABELS[status]||status||'Em preparação'}
  function statusClass(status){return String(status||'').toLowerCase().replace(/[^a-z0-9]+/g,'-')}
  function userLabel(id){return (getDb().users||[]).find(item=>item.id===id)?.name?.split(' — ')[0]||'Equipe Purple'}
  function totalStageMinutes(plan){return LESSON_STAGES.reduce((sum,stage)=>sum+Number(plan?.stages?.[stage.key]?.duration||0),0)}
  function saveHistory(plan,action,detail){plan.history=plan.history||[];plan.history.unshift({id:uid('hist-lp'),at:new Date().toISOString(),actor:userLabel(getUser()?.id),action,detail})}
  function bumpPlan(plan){plan.revision=Number(plan.revision||1)+1;const meta=findLessonMeta(plan.lessonId);if(meta.lesson){meta.lesson.status=plan.status;meta.lesson.version=plan.version}}
  async function savePlan(){try{return await persist()}catch(error){console.warn('Lesson Plans — persistência remota não concluída:',error);return false}}
  function setView(next){getState().lessonPlans={...(getState().lessonPlans||{}),mode:'read',...next};window.App?.renderPage?.()}
  function goModule(page='lesson-plans'){if(getState().page!==page)window.App?.go?.(page)}
  function openLibrary(){setView({view:'library',collectionId:'',courseId:'',unitId:'',lessonId:''});goModule()}
  function openCollection(collectionId){setView({view:'collection',collectionId,courseId:'',unitId:'',lessonId:''});goModule()}
  function openCourse(courseId){const c=findCourse(courseId);setView({view:'book',collectionId:c.collectionId,courseId,unitId:'',lessonId:''});goModule()}
  function openUnit(courseId,unitId){const c=findCourse(courseId);setView({view:'unit',collectionId:c.collectionId,courseId,unitId,lessonId:''});goModule()}
  function openLesson(lessonId){const m=findLessonMeta(lessonId),plan=findPlan(lessonId);if(!m.lesson)return toast('Aula não encontrada.');if(plan?.basePdf?.storagePath)signedStorageUrl(plan.basePdf.storagePath).then(url=>{plan.basePdf.url=url;if(getState().lessonPlans?.lessonId===lessonId)window.App?.renderPage?.()}).catch(error=>console.warn('Lesson Plans — Plano Base sem assinatura atual:',error));ensureWorkspace().lastOpened={courseId:m.course.id,unitId:m.unit.id,lessonId};setView({view:'lesson',collectionId:m.course.collectionId,courseId:m.course.id,unitId:m.unit.id,lessonId,mode:'read'});goModule()}
  function setLessonTab(tab){getState().lessonPlans={...(getState().lessonPlans||{}),lessonTab:tab||'base'};window.App?.renderPage?.()}
  function canManagePlanning(){return can('lesson_plans.review')||can('lesson_plans.publish')||can('lesson_plans.cycles.manage')}
  function openManagement(){if(!canManagePlanning())return openLibrary();setView({view:'management'});goModule()}
  async function openBookViewer(courseId,page=1){const c=findCourse(courseId);if(c.pdfStoragePath){try{const url=await signedStorageUrl(c.pdfStoragePath);if(url)c.pdfUrl=url}catch(error){console.error('Lesson Plans — erro ao assinar PDF:',error);toast(`Não foi possível abrir o PDF seguro: ${error.message||error}`)}}setView({view:'viewer',collectionId:c.collectionId,courseId,viewerPage:pageFrom(page),viewerZoom:100});goModule()}
  function openStageInBook(lessonId,stageKey){const m=findLessonMeta(lessonId);const s=findPlan(lessonId)?.stages?.[stageKey]||{};openBookViewer(m.course.id,s.studentBookPages||s.pages||1)}
  async function openPdfViewer(doc){if(doc?.storagePath&&!doc.url){doc.url=await signedStorageUrl(doc.storagePath)}getState().lessonPlans={...(getState().lessonPlans||{}),view:'pdf-viewer',pdfViewer:{...doc,page:pageFrom(doc?.page||1),zoom:100}};goModule();window.App?.renderPage?.()}
  function setEditMode(lessonId){const m=findLessonMeta(lessonId);setView({view:'lesson',collectionId:m.course.collectionId,courseId:m.course.id,unitId:m.unit.id,lessonId,mode:'edit'})}

  function renderCover(item,kind='book'){return item.coverUrl?`<div class="lp-cover ${kind}"${coverStyle(item)}></div>`:`<div class="lp-cover ${kind} placeholder"><span>${escape(item.name?.slice(0,2).toUpperCase()||'PW')}</span><small>Capa real não cadastrada</small></div>`}
  function renderCrumbs(items){return `<div class="lp-crumbs"><button onclick="PurpleLessonPlans.openLibrary()">Coleções</button>${items.map(item=>`<span>›</span><button onclick="${item.action}">${escape(item.label)}</button>`).join('')}</div>`}
  function renderLessonNav(active='library'){const manage=canManagePlanning();const items=[['library','Biblioteca','PurpleLessonPlans.openLibrary()'],['plans','Planejamentos',manage?'PurpleLessonPlans.openManagement()':'PurpleLessonPlans.openLibrary()'],['contributions','Minhas contribuições',"window.App.go('lesson-contributions')"]];if(manage)items.push(['management','Gestão','PurpleLessonPlans.openManagement()']);return `<nav class="lp-subnav">${items.map(([id,label,action])=>`<button class="${active===id?'active':''}" onclick="${action}">${escape(label)}</button>`).join('')}</nav>`}
  function libraryStatusLabel(status){return {active:'Ativa',draft:'Em preparo',archived:'Arquivada'}[status]||status||'Em preparo'}

  function renderTeacherHome(){
    const w=ensureWorkspace(),last=w.lastOpened||{},m=findLessonMeta(last.lessonId||'discover-u01-l01'),mine=w.contributions.filter(item=>item.assigneeId===getUser()?.id&&['on_track','due_today','overdue'].includes(item.status)),books=collectionBooks(findCollection('purple-way')).slice(0,5);
    return `<div class="page lesson-home-page lp-library-shell"><section class="lp-teacher-hero"><div><span class="eyebrow">Biblioteca Pedagógica Purple</span><h1>${escape(typeof window.greeting==='function'?window.greeting():'Olá!')}</h1><p>Encontre a aula, consulte o livro, use os recursos e contribua para melhorar como a Purple ensina.</p></div><button class="btn primary" onclick="PurpleLessonPlans.openLibrary()">Abrir Biblioteca</button></section><section class="lp-home-continue"><div><span class="eyebrow">Continuar de onde parei</span><h2>${escape(m.course?.name||'Discover')} • ${escape(m.unit?.title||'Unit 01')} • ${escape(m.lesson?.title||'Lesson 01')}</h2><p>${escape(m.lesson?.theme||'Meet the group')}</p></div><button class="btn primary" onclick="PurpleLessonPlans.openLesson('${escape(last.lessonId||'discover-u01-l01')}')">Continuar aula</button></section><div class="lp-home-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">Minha biblioteca</span><h3>Purple Way</h3></div></div><div class="lp-mini-book-row">${books.map(book=>`<button onclick="PurpleLessonPlans.openCourse('${escape(book.id)}')">${renderCover(book,'mini')}<b>${escape(book.name)}</b></button>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">Precisa da sua contribuição</span><h3>${fmtNumber(mine.length)} item(ns)</h3></div></div>${mine.slice(0,2).map(item=>{const meta=findLessonMeta(item.lessonId);return `<article class="lp-compact-action"><b>${escape(meta.course?.name)} • ${escape(meta.unit?.title)}</b><span>${escape(meta.lesson?.title)} • ${escape(item.stageKey)}</span><button class="btn ghost small" onclick="PurpleLessonPlans.openLesson('${escape(item.lessonId)}')">Contribuir</button></article>`}).join('')||'<p class="muted">Nada urgente agora. Biblioteca liberada para preparar aula.</p>'}</section></div><section class="panel"><div class="panel-head"><div><span class="eyebrow">Novos planos publicados</span><h3>Atualizações da Biblioteca</h3></div></div><div class="lp-published-row">${w.publishedFeed.slice(0,3).map(item=>{const meta=findLessonMeta(item.lessonId);return `<button onclick="PurpleLessonPlans.openLesson('${escape(item.lessonId)}')"><b>${escape(meta.course?.name)} • ${escape(meta.unit?.title)}</b><span>${escape(meta.lesson?.title)} publicado em ${fmtDate(item.publishedAt)}</span></button>`}).join('')||'<p class="muted">Nenhuma publicação recente.</p>'}</div></section></div>`;
  }

  function renderLibrary(){
    const w=ensureWorkspace(),state=getState().lessonPlans||{},term=String(state.searchTerm||'').trim().toLowerCase();
    const manage=canManageOfficial();
    return `<div class="page lesson-page lp-library-shell">${renderLessonNav('library')}<section class="lp-library-hero"><div><span class="eyebrow">Biblioteca pedagógica digital</span><h1>Como a Purple ensina.</h1><p>Explore por coleção, livro, unidade e aula. A colaboração existe para melhorar essa biblioteca, não para roubar a cena.</p></div><div class="lp-search-box"><label>Qual aula você vai ensinar?</label><input id="lpLibrarySearch" value="${escape(state.searchTerm||'')}" oninput="PurpleLessonPlans.updateSearch(this.value)" placeholder="Discover, Unit 1, simple past, food, introductions, speaking..."/></div></section>${term?renderSearchResults(term):`<section><div class="section-title"><div><span class="eyebrow">Coleções</span><h2>Programas Purple</h2></div><div class="section-actions">${manage?'<button class="btn primary" onclick="PurpleLessonPlans.openCollectionEditor()">+ Nova coleção</button>':''}</div></div><div class="lp-collection-grid">${w.collections.sort((a,b)=>a.order-b.order).map(collection=>`<article class="lp-collection-card-wrap"><button class="lp-collection-card" onclick="PurpleLessonPlans.openCollection('${escape(collection.id)}')">${renderCover(collection,'collection')}<span>${escape(libraryStatusLabel(collection.status))}</span><h3>${escape(collection.name)}</h3><p>${escape(collection.description)}</p><small>${fmtNumber(collectionBooks(collection).length)} livros/programas</small></button>${manage?`<div class="lp-collection-actions"><button class="btn ghost small" onclick="PurpleLessonPlans.openCollectionEditor('${escape(collection.id)}')">Editar</button><button class="btn danger small" onclick="PurpleLessonPlans.deleteCollection('${escape(collection.id)}')">Excluir</button></div>`:''}</article>`).join('')}</div></section>`}</div>`;
  }

  function renderSearchResults(term){
    const results=[],matches=value=>String(value||'').toLowerCase().includes(term);
    for(const course of ensureWorkspace().courses){if(matches([course.name,course.description,course.level].join(' ')))results.push(['Livro',course.name,course.description,`PurpleLessonPlans.openCourse('${escape(course.id)}')`]);for(const unit of course.units||[]){if(matches([unit.title,unit.theme,unit.objective,unit.content,(unit.vocabulary||[]).join(' '),(unit.grammar||[]).join(' '),(unit.skills||[]).join(' ')].join(' ')))results.push(['Unidade',`${course.name} • ${unit.title}`,unit.theme,`PurpleLessonPlans.openUnit('${escape(course.id)}','${escape(unit.id)}')`]);for(const lesson of unit.lessons||[]){const plan=findPlan(lesson.id);if(matches([lesson.title,lesson.theme,lesson.communicativeObjective,plan?.communicativeObjective,Object.values(plan?.stages||{}).map(stage=>[stage.objective,stage.activity,stage.instructions,stage.pages].join(' ')).join(' ')].join(' ')))results.push(['Aula',`${course.name} • ${unit.title} • ${lesson.title}`,lesson.theme,`PurpleLessonPlans.openLesson('${escape(lesson.id)}')`]);}}}
    return `<section class="panel lp-search-results"><div class="panel-head"><div><span class="eyebrow">Resultados</span><h3>${fmtNumber(results.length)} resultado(s) para “${escape(term)}”</h3></div></div><div class="lp-result-list">${results.map(([kind,title,subtitle,action])=>`<button onclick="${action}"><span>${escape(kind)}</span><b>${escape(title)}</b><small>${escape(subtitle)}</small></button>`).join('')||'<p class="muted">Nenhum conteúdo encontrado.</p>'}</div></section>`;
  }

  function renderCollection(){
    const collection=findCollection(getState().lessonPlans?.collectionId),books=collectionBooks(collection);
    const manage=canManageOfficial();
    return `<div class="page lesson-page lp-library-shell">${renderLessonNav('library')}${renderCrumbs([{label:collection.name,action:`PurpleLessonPlans.openCollection('${escape(collection.id)}')`}])}<section class="lp-collection-head">${renderCover(collection,'collection-large')}<div><span class="eyebrow">Coleção</span><h1>${escape(collection.name)}</h1><p>${escape(collection.description)}</p><div class="section-actions" style="justify-content:flex-start">${manage?`<button class="btn ghost" onclick="PurpleLessonPlans.openCollectionEditor('${escape(collection.id)}')">Gerenciar coleção</button><button class="btn primary" onclick="PurpleLessonPlans.openCollectionBookEditor('${escape(collection.id)}')">Adicionar livro/programa</button>`:''}</div></div></section><div class="lp-book-grid">${books.map(book=>`<article class="lp-book-card">${manage?`<div class="lp-book-admin-actions"><button class="btn ghost small" onclick="PurpleLessonPlans.openCollectionBookEditor('${escape(collection.id)}','${escape(book.id)}')">Alterar</button><button class="btn danger small" onclick="PurpleLessonPlans.deleteCollectionBook('${escape(collection.id)}','${escape(book.id)}')">Excluir</button></div>`:''}<button class="lp-book-open" onclick="PurpleLessonPlans.openCourse('${escape(book.id)}')">${renderCover(book,'book')}<div><span>${escape(book.level||'')}</span><h3>${escape(book.name)}</h3><p>${escape(book.description)}</p><small>${fmtNumber((book.units||[]).length)} unidades • ${escape(libraryStatusLabel(book.status))}</small></div></button></article>`).join('')||`<div class="empty"><h3>Coleção vazia</h3><p>Adicione o primeiro livro ou programa desta coleção.</p>${manage?`<button class="btn primary" onclick="PurpleLessonPlans.openCollectionBookEditor('${escape(collection.id)}')">Adicionar livro/programa</button>`:''}</div>`}</div></div>`;
  }

  function renderBook(){
    const course=findCourse(getState().lessonPlans?.courseId),collection=findCollection(course.collectionId),units=course.units||[],totalLessons=units.reduce((s,u)=>s+(u.lessons||[]).length,0);
    const manage=canManageOfficial();
    return `<div class="page lesson-page lp-library-shell">${renderLessonNav('library')}${renderCrumbs([{label:collection.name,action:`PurpleLessonPlans.openCollection('${escape(collection.id)}')`},{label:course.name,action:`PurpleLessonPlans.openCourse('${escape(course.id)}')`}])}<section class="lp-book-head">${renderCover(course,'book-large')}<div><span class="eyebrow">Livro</span><h1>${escape(course.name)}</h1><p>${escape(course.description)}</p><div class="lp-meta-row"><span>${escape(course.level||'Nível não cadastrado')}</span><span>${fmtNumber(units.length)} unidades</span><span>${fmtNumber(totalLessons)} aulas</span></div><p><b>Cobertura pedagógica:</b> ${escape(course.pedagogicalInfo||'Em cadastramento.')}</p><div class="section-actions" style="justify-content:flex-start"><button class="btn primary" onclick="PurpleLessonPlans.openBookViewer('${escape(course.id)}',1)">Abrir livro</button>${manage?`<button class="btn ghost" onclick="PurpleLessonPlans.openBookEditor('${escape(course.id)}')">Gerenciar livro</button>`:''}</div></div></section><section><div class="section-title"><div><span class="eyebrow">Unidades</span><h2>${escape(course.name)}</h2><p>Organize as unidades que aparecem dentro deste livro da coleção.</p></div>${manage?`<div class="section-actions"><button class="btn primary" onclick="PurpleLessonPlans.openUnitEditor('${escape(course.id)}')">Nova unidade</button></div>`:''}</div><div class="lp-unit-grid">${units.map(unit=>{const counts=lessonCounts(unit),resources=(unit.lessons||[]).reduce((s,l)=>s+(findPlan(l.id)?.resources||[]).length,0);return `<article class="lp-unit-card"><button class="lp-unit-open" onclick="PurpleLessonPlans.openUnit('${escape(course.id)}','${escape(unit.id)}')"><span>${escape(unit.title)}</span><h3>${escape(unit.theme)}</h3><p>${escape(unit.subtitle||unit.objective||'Unidade pronta para receber título, subtítulo, PDF e aulas.')}</p><div><b>${counts.ready?`${counts.ready} plano(s) disponível(is)`:'Em preparação'}</b><small>${fmtNumber(resources)} recursos</small></div></button>${manage?`<div class="lp-unit-admin-actions"><button class="btn ghost small" onclick="PurpleLessonPlans.openUnitEditor('${escape(course.id)}','${escape(unit.id)}')">Editar</button><button class="btn danger small" onclick="PurpleLessonPlans.deleteUnit('${escape(course.id)}','${escape(unit.id)}')">Excluir</button></div>`:''}</article>`}).join('')||`<div class="empty"><h3>Unidades em preparação</h3><p>Este livro já está pronto para receber conteúdo pedagógico.</p>${manage?`<button class="btn primary" onclick="PurpleLessonPlans.openUnitEditor('${escape(course.id)}')">Criar primeira unidade</button>`:''}</div>`}</div></section></div>`;
  }

  function signUnitPdfIfNeeded(unit){
    if(unit?.basePdf?.storagePath&&!unit.basePdf.url)signedStorageUrl(unit.basePdf.storagePath).then(url=>{if(url){unit.basePdf.url=url;window.App?.renderPage?.()}}).catch(error=>console.error('Lesson Plans — erro ao assinar PDF da unidade:',error));
  }
  function renderUnit(){
    const s=getState().lessonPlans||{},course=findCourse(s.courseId),unit=findUnit(course.id,s.unitId);
    signUnitPdfIfNeeded(unit);
    return `<div class="page lesson-page lp-library-shell">${renderLessonNav('library')}${renderCrumbs([{label:findCollection(course.collectionId).name,action:`PurpleLessonPlans.openCollection('${escape(course.collectionId)}')`},{label:course.name,action:`PurpleLessonPlans.openCourse('${escape(course.id)}')`},{label:unit.title,action:`PurpleLessonPlans.openUnit('${escape(course.id)}','${escape(unit.id)}')`}])}<section class="lp-unit-hero"><div><span class="eyebrow">${escape(course.name)}</span><h1>${escape(unit.title)} — ${escape(unit.theme)}</h1><p>${escape(unit.subtitle||unit.objective)}</p></div><div class="section-actions">${canManageOfficial()?`<button class="btn ghost" onclick="PurpleLessonPlans.openUnitMapEditor('${escape(course.id)}','${escape(unit.id)}')">Editar unidade</button><button class="btn primary" onclick="PurpleLessonPlans.openUnitPdfEditor('${escape(course.id)}','${escape(unit.id)}')">${unit.basePdf?.storagePath?'Substituir PDF da unidade':'Lançar PDF da unidade'}</button>`:''}<button class="btn soft" onclick="PurpleLessonPlans.openBookViewer('${escape(course.id)}','${escape(unit.studentBookPages||1)}')">Abrir livro</button></div></section>${renderUnitPdfPanel(course,unit)}${renderUnitSupportInfo(unit,course)}</div>`;
  }

  function renderUnitPdfPanel(course,unit){
    const pdf=unit.basePdf;
    return `<section class="lp-unit-plan-reader">${pdf?.storagePath?`<div class="lp-document-stage unit"><div class="lp-document-toolbar"><div><span class="eyebrow">Plano padrão da unidade</span><h3>${escape(pdf.fileName||`${unit.title} — ${unit.theme}.pdf`)}</h3><small>${escape(course.name)} • ${escape(unit.title)}${pdf.version?` • ${escape(pdf.version)}`:''}${pdf.updatedAt?` • atualizado em ${fmtDateTime(pdf.updatedAt)}`:''}</small></div><div class="section-actions"><button class="btn primary small" onclick="PurpleLessonPlans.openUnitPdf('${escape(course.id)}','${escape(unit.id)}')">Abrir em foco</button>${canManageOfficial()?`<button class="btn ghost small" onclick="PurpleLessonPlans.openUnitPdfEditor('${escape(course.id)}','${escape(unit.id)}')">Substituir PDF</button>`:''}</div></div><iframe title="Plano da unidade ${escape(unit.title)}" loading="lazy" src="${escape(pdf.url||'')}"></iframe></div>`:`<div class="lp-empty-reader unit"><span>Plano padrão da unidade</span><h2>PDF da unidade ainda não lançado.</h2><p>Quando a coordenação enviar o plano oficial da unidade inteira, o professor verá o documento aqui, antes de abrir qualquer Lesson específica.</p>${canManageOfficial()?`<button class="btn primary" onclick="PurpleLessonPlans.openUnitPdfEditor('${escape(course.id)}','${escape(unit.id)}')">Lançar PDF da unidade</button>`:''}</div>`}</section>`;
  }

  function renderUnitSupportInfo(unit,course){
    const entries=[['Objetivos',unit.objective],['Conteúdo',unit.content||unit.theme],['Vocabulary',(unit.vocabulary||[]).join(' • ')],['Grammar / Language',(unit.grammar||[]).join(' • ')],['Communicative Functions',(unit.communicativeFunctions||[]).join(' • ')],['Expected Outcomes',unit.expectedOutcome],['Skills',(unit.skills||[]).join(' • ')],['Páginas do livro',`Student Book ${unit.studentBookPages||'—'} • Workbook ${unit.workbookPages||'—'}`]];
    return `<section class="lp-unit-support"><details><summary><div><span class="eyebrow">Informações da unidade</span><strong>Referências complementares</strong><small>Opcional. O PDF acima é a fonte principal do plano da unidade.</small></div><button class="btn soft small" onclick="event.preventDefault();PurpleLessonPlans.openBookViewer('${escape(course.id)}','${escape(unit.studentBookPages||1)}')">Abrir páginas</button></summary><div class="lp-summary-grid">${entries.map(([label,value])=>`<div><span>${escape(label)}</span><p>${escape(value||'—')}</p></div>`).join('')}</div></details></section>`;
  }

  function renderLesson(){
    const s=getState().lessonPlans||{},m=findLessonMeta(s.lessonId),plan=findPlan(s.lessonId);if(!m.lesson||!plan)return `<div class="page"><div class="empty"><h3>Planejamento não encontrado</h3><p>Selecione uma aula da biblioteca.</p></div></div>`;
    if(plan.basePdf?.storagePath&&!plan.basePdf.url)signedStorageUrl(plan.basePdf.storagePath).then(url=>{if(url){plan.basePdf.url=url;window.App?.renderPage?.()}}).catch(error=>console.error('Lesson Plans — erro ao assinar Plano Base:',error));
    const cycle=findCycle(plan.cycleId),tab=s.lessonTab||'base';
    return `<div class="page lesson-page lp-library-shell lp-reader-page">${renderLessonNav('library')}${renderCrumbs([{label:findCollection(m.course.collectionId).name,action:`PurpleLessonPlans.openCollection('${escape(m.course.collectionId)}')`},{label:m.course.name,action:`PurpleLessonPlans.openCourse('${escape(m.course.id)}')`},{label:m.unit.title,action:`PurpleLessonPlans.openUnit('${escape(m.course.id)}','${escape(m.unit.id)}')`},{label:m.lesson.title,action:`PurpleLessonPlans.openLesson('${escape(plan.lessonId)}')`}])}<section class="lp-reader-head"><div><span class="eyebrow">${escape(m.course.name)} • ${escape(m.unit.title)}${plan.meetingNumber?` · Meeting ${fmtNumber(plan.meetingNumber)}`:''}</span><h1>${escape(plan.theme||m.lesson.theme)}</h1><p>${escape(plan.communicativeObjective||m.lesson.communicativeObjective)}</p><div class="lp-meta-row"><span>Plano Base Purple</span><span>${escape(plan.bookPages||m.lesson.bookPages||'Páginas em cadastro')}</span><span>${fmtNumber(plan.duration)} min + 10 break</span></div></div><div class="section-actions"><button class="btn soft" onclick="PurpleLessonPlans.openBookViewer('${escape(m.course.id)}','${escape(m.unit.studentBookPages||plan.bookPages||1)}')">Abrir livro</button>${canManageOfficial()?`<button class="btn primary" onclick="PurpleLessonPlans.openBasePdfEditor('${escape(plan.lessonId)}')">${plan.basePdf?.storagePath?'Substituir Plano Base':'Enviar Plano Base'}</button>`:''}</div></section>${renderLessonTabs(plan,tab)}<section class="lp-reader-content">${renderLessonTabContent(plan,m,cycle,tab)}</section></div>`;
  }

  function approvedResources(plan,category){return (plan.resources||[]).filter(item=>(item.category||'')===category).filter(item=>item.status==='approved'||item.contributorId===getUser()?.id||canManageOfficial())}
  function renderLessonTabs(plan,active){const extras=approvedResources(plan,'extra').length,links=approvedResources(plan,'media').length,contrib=(plan.resources||[]).filter(item=>item.source==='team'||item.contributorId).length;const tabs=[['base','Plano Base',''],['extras','Atividades Extras',extras],['media','Links & Mídia',links],['contrib','Contribuições',contrib]];return `<nav class="lp-lesson-tabs">${tabs.map(([id,label,count])=>`<button class="${active===id?'active':''}" onclick="PurpleLessonPlans.setLessonTab('${id}')">${escape(label)}${count?` <b>${fmtNumber(count)}</b>`:''}</button>`).join('')}</nav>`}
  function renderLessonTabContent(plan,m,cycle,tab){if(tab==='extras')return renderExtraActivities(plan);if(tab==='media')return renderMediaLinks(plan);if(tab==='contrib')return `${renderCollectiveContribution(plan,cycle)}${renderHistory(plan)}${renderFeedback(plan)}`;return renderBasePdfPanel(plan,m)}
  function renderBasePdfPanel(plan,m){const pdf=plan.basePdf;return `<section class="lp-base-reader">${pdf?.storagePath?`<div class="lp-document-stage"><div class="lp-document-toolbar"><div><span class="eyebrow">Plano Base Purple</span><h3>${escape(pdf.fileName||'PDF oficial da Lesson')}</h3><small>Atualizado em ${fmtDateTime(pdf.updatedAt)}${pdf.version?` • ${escape(pdf.version)}`:''}</small></div><div class="section-actions"><button class="btn primary small" onclick="PurpleLessonPlans.openBasePdf('${escape(plan.lessonId)}')">Abrir plano</button>${canManageOfficial()?`<button class="btn ghost small" onclick="PurpleLessonPlans.openBasePdfEditor('${escape(plan.lessonId)}')">Substituir PDF</button>`:''}</div></div><iframe title="Plano Base ${escape(plan.theme)}" loading="lazy" src="${escape(pdf.url||'')}"></iframe></div>`:`<div class="lp-empty-reader"><span>Plano Base Purple</span><h2>Plano Base ainda não disponível.</h2><p>Quando a coordenação enviar o PDF oficial, ele aparecerá aqui como documento principal da aula.</p>${canManageOfficial()?`<button class="btn primary" onclick="PurpleLessonPlans.openBasePdfEditor('${escape(plan.lessonId)}')">Enviar Plano Base PDF</button>`:''}</div>`}</section><section class="lp-legacy-support"><details><summary>Ver estrutura pedagógica legada</summary>${renderMeetingOverview(plan,m)}${renderTeacherQuickView(plan)}${renderRapidCompact(plan)}${renderLearningArcs(plan)}${renderLessonFlow(plan,false)}</details></section>`}
  function renderExtraActivities(plan){const items=approvedResources(plan,'extra');return `<section class="panel lp-resource-section"><div class="panel-head"><div><span class="eyebrow">Atividades extras</span><h3>Materiais complementares da Lesson</h3><small>Opcional. Use e imprima somente quando fizer sentido para a aula.</small></div>${canContribute()?`<button class="btn primary small" onclick="PurpleLessonPlans.openExtraActivityEditor('${escape(plan.lessonId)}')">Adicionar atividade</button>`:''}</div><div class="lp-resource-grid premium">${items.map(item=>renderLessonResourceCard(item,'extra')).join('')||'<div class="lp-empty-inline"><b>Nenhuma atividade extra nesta Lesson.</b><span>PDFs complementares aparecerão aqui sem virar obrigação de impressão.</span></div>'}</div></section>`}
  function renderMediaLinks(plan){const items=approvedResources(plan,'media');return `<section class="panel lp-resource-section"><div class="panel-head"><div><span class="eyebrow">Links & Mídia</span><h3>Jogos, vídeos e recursos externos</h3><small>Links abrem com segurança fora do viewer quando o site externo exigir.</small></div>${canContribute()?`<button class="btn primary small" onclick="PurpleLessonPlans.openMediaLinkEditor('${escape(plan.lessonId)}')">Adicionar link</button>`:''}</div><div class="lp-resource-grid premium">${items.map(item=>renderLessonResourceCard(item,'media')).join('')||'<div class="lp-empty-inline"><b>Nenhum recurso externo adicionado.</b><span>Kahoot, Wordwall, vídeos e jogos podem ser sugeridos pela equipe.</span></div>'}</div></section>`}
  function renderLessonResourceCard(item,category){const pending=item.status==='pending';return `<article class="lp-resource-card premium ${pending?'pending':''}"><div class="lp-resource-icon">${category==='extra'?'PDF':'LINK'}</div><div><span>${escape(item.type||'Recurso')}${pending?' • Pendente':''}</span><h4>${escape(item.title)}</h4><p>${escape(item.description||item.whenToUse||'Material complementar.')}</p><small>${escape(item.fileName||item.url||'')}${item.contributorName?` • ${escape(item.contributorName)}`:''}${item.uploadedAt?` • ${fmtDate(item.uploadedAt)}`:''}</small><div class="section-actions" style="justify-content:flex-start">${category==='extra'?`<button class="btn primary small" onclick="PurpleLessonPlans.openResourcePdf('${escape(item.id)}')">Visualizar</button><button class="btn ghost small" onclick="PurpleLessonPlans.printResourcePdf('${escape(item.id)}')">Imprimir</button>`:`<button class="btn primary small" onclick="PurpleLessonPlans.openResource('${escape(item.id)}')">Abrir</button>`}${canManageOfficial()&&pending?`<button class="btn soft small" onclick="PurpleLessonPlans.approveResource('${escape(item.id)}')">Aprovar</button>`:''}</div></div></article>`}

  function openBasePdfEditor(lessonId){if(!canManageOfficial())return toast('Somente coordenação/direção substitui o Plano Base oficial.');const plan=findPlan(lessonId),current=plan?.basePdf;window.modal?.(`<div class="modal-head"><div><span class="eyebrow">Plano Base Purple</span><h3>${current?'Substituir PDF oficial':'Enviar PDF oficial'}</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="lp-upload-modal"><p>O PDF será salvo no Storage seguro e só passará a valer depois de persistir no cadastro da Lesson.</p>${current?`<div class="alert blue"><div class="alert-icon">i</div><div><b>Versão atual preservada até o novo save concluir.</b><span>${escape(current.fileName||'Plano Base atual')} • ${fmtDateTime(current.updatedAt)}</span></div></div>`:''}<div class="form-grid cols-2"><div class="field"><label>Versão/revisão</label><input id="lpBasePdfVersion" value="${escape(current?.version||`Rev. ${Number(plan.revision||1)+1}`)}"/></div><div class="field"><label>Arquivo PDF</label><input id="lpBasePdfFile" type="file" accept="application/pdf"/></div></div><small id="lpBasePdfStatus">Selecione um PDF oficial.</small></div><div class="section-actions"><button class="btn ghost" onclick="window.App.closeModal()">Cancelar</button><button id="lpBasePdfSave" class="btn primary" onclick="PurpleLessonPlans.saveBasePdf('${escape(lessonId)}')">${current?'Substituir Plano Base':'Salvar Plano Base'}</button></div>`,true)}
  async function saveBasePdf(lessonId){if(!canManageOfficial())return toast('Somente coordenação/direção substitui o Plano Base oficial.');const button=document.getElementById('lpBasePdfSave'),status=document.getElementById('lpBasePdfStatus'),file=document.getElementById('lpBasePdfFile')?.files?.[0],version=document.getElementById('lpBasePdfVersion')?.value.trim()||'';try{assertFile(file,{kind:'Plano Base',types:['application/pdf'],extensions:['pdf'],maxSize:80*1024*1024});if(button){button.disabled=true;button.textContent='Enviando...'}if(status)status.textContent='Enviando PDF...';const ext='pdf',path=`plans/${safeName(lessonId)}/base-${Date.now()}.${ext}`,url=await uploadToLessonStorage(path,file);if(status)status.textContent='Salvando cadastro...';const plan=findPlan(lessonId),previous=plan.basePdf;plan.basePdf={storagePath:path,url,fileName:file.name,fileSize:file.size,mimeType:file.type||'application/pdf',version,updatedAt:new Date().toISOString(),updatedBy:getUser()?.id,updatedByName:getUser()?.name||'Equipe Purple'};saveHistory(plan,previous?'Substituiu Plano Base PDF':'Enviou Plano Base PDF',`${plan.basePdf.updatedByName} associou ${file.name}.`);bumpPlan(plan);await savePlan();window.App.closeModal();setLessonTab('base');toast('Plano Base salvo.')}catch(error){console.error('Lesson Plans — Plano Base PDF:',error);if(status)status.textContent=`Erro: ${error.message||error}`;toast(`Não foi possível salvar o Plano Base: ${error.message||error}`)}finally{if(button){button.disabled=false;button.textContent='Salvar Plano Base'}}}
  async function openBasePdf(lessonId){const plan=findPlan(lessonId);if(!plan?.basePdf?.storagePath)return toast('Plano Base ainda não disponível.');await openPdfViewer({kind:'base',lessonId,title:`Plano Base • ${plan.theme}`,storagePath:plan.basePdf.storagePath,fileName:plan.basePdf.fileName,page:1})}
  function openUnitPdfEditor(courseId,unitId){if(!canManageOfficial())return toast('Somente coordenação/direção lança o PDF padrão da unidade.');const unit=findUnit(courseId,unitId),course=findCourse(courseId),current=unit?.basePdf;window.modal?.(`<div class="modal-head"><div><span class="eyebrow">Plano padrão da unidade</span><h3>${current?'Substituir PDF da unidade':'Lançar PDF da unidade'}</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="lp-upload-modal"><p>Este PDF é o documento principal da unidade inteira. Ele aparece automaticamente na página da Unit, antes da lista de Lessons.</p>${current?`<div class="alert blue"><div class="alert-icon">i</div><div><b>PDF atual permanece até o novo save concluir.</b><span>${escape(current.fileName||'Plano atual')} • ${fmtDateTime(current.updatedAt)}</span></div></div>`:''}<div class="form-grid cols-2"><div class="field"><label>Versão/revisão</label><input id="lpUnitPdfVersion" value="${escape(current?.version||`Rev. ${Number(unit.revision||1)+1}`)}"/></div><div class="field"><label>Arquivo PDF</label><input id="lpUnitPdfFile" type="file" accept="application/pdf"/></div></div><small id="lpUnitPdfStatus">${escape(course.name)} • ${escape(unit.title)} — selecione o PDF oficial da unidade.</small></div><div class="section-actions"><button class="btn ghost" onclick="window.App.closeModal()">Cancelar</button><button id="lpUnitPdfSave" class="btn primary" onclick="PurpleLessonPlans.saveUnitPdf('${escape(courseId)}','${escape(unitId)}')">${current?'Substituir PDF':'Lançar PDF'}</button></div>`,true)}
  async function saveUnitPdf(courseId,unitId){if(!canManageOfficial())return toast('Somente coordenação/direção lança o PDF padrão da unidade.');const button=document.getElementById('lpUnitPdfSave'),status=document.getElementById('lpUnitPdfStatus'),file=document.getElementById('lpUnitPdfFile')?.files?.[0],version=document.getElementById('lpUnitPdfVersion')?.value.trim()||'',unit=findUnit(courseId,unitId);try{assertFile(file,{kind:'PDF da unidade',types:['application/pdf'],extensions:['pdf'],maxSize:100*1024*1024});if(button){button.disabled=true;button.textContent='Enviando...'}if(status)status.textContent='Enviando PDF da unidade...';const path=`units/${safeName(courseId)}/${safeName(unitId)}/base-${Date.now()}.pdf`,url=await uploadToLessonStorage(path,file);if(status)status.textContent='Salvando cadastro da unidade...';unit.basePdf={storagePath:path,url,fileName:file.name,fileSize:file.size,mimeType:file.type||'application/pdf',version,updatedAt:new Date().toISOString(),updatedBy:getUser()?.id,updatedByName:getUser()?.name||'Equipe Purple'};unit.updatedAt=new Date().toISOString();await savePlan();window.App.closeModal();openUnit(courseId,unitId);toast('PDF padrão da unidade lançado.')}catch(error){console.error('Lesson Plans — PDF da unidade:',error);if(status)status.textContent=`Erro: ${error.message||error}`;toast(`Não foi possível salvar o PDF da unidade: ${error.message||error}`)}finally{if(button){button.disabled=false;button.textContent='Lançar PDF'}}}
  async function openUnitPdf(courseId,unitId){const unit=findUnit(courseId,unitId),course=findCourse(courseId);if(!unit?.basePdf?.storagePath)return toast('PDF da unidade ainda não lançado.');await openPdfViewer({kind:'unit',courseId,unitId,title:`Plano da unidade • ${course.name} • ${unit.title} — ${unit.theme}`,storagePath:unit.basePdf.storagePath,fileName:unit.basePdf.fileName,page:1})}
  function openExtraActivityEditor(lessonId){if(!canContribute())return toast('Contribuição não autorizada.');window.modal?.(`<div class="modal-head"><div><span class="eyebrow">Atividade extra</span><h3>Adicionar PDF complementar</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="lp-upload-modal"><div class="form-grid cols-2"><div class="field"><label>Título</label><input id="lpExtraTitle" placeholder="Ex.: Speaking Cards"/></div><div class="field"><label>Tipo</label><select id="lpExtraType">${EXTRA_ACTIVITY_TYPES.map(type=>`<option>${escape(type)}</option>`).join('')}</select></div><div class="field"><label>Arquivo PDF</label><input id="lpExtraFile" type="file" accept="application/pdf"/></div><div class="field"><label>Quando usar</label><input id="lpExtraWhen" placeholder="Ex.: Review • 5-10 min"/></div></div><div class="field"><label>Descrição curta</label><textarea id="lpExtraDescription" placeholder="Explique em uma frase como usar sem tornar obrigatório."></textarea></div><small id="lpExtraStatus">Material complementar. Imprimir somente se utilizar.</small></div><div class="section-actions"><button class="btn ghost" onclick="window.App.closeModal()">Cancelar</button><button id="lpExtraSave" class="btn primary" onclick="PurpleLessonPlans.saveExtraActivity('${escape(lessonId)}')">Salvar atividade</button></div>`,true)}
  async function saveExtraActivity(lessonId){const button=document.getElementById('lpExtraSave'),status=document.getElementById('lpExtraStatus'),file=document.getElementById('lpExtraFile')?.files?.[0],title=document.getElementById('lpExtraTitle')?.value.trim()||file?.name?.replace(/\.[^.]+$/,'')||'Atividade extra';try{assertFile(file,{kind:'atividade extra',types:['application/pdf'],extensions:['pdf'],maxSize:50*1024*1024});if(button){button.disabled=true;button.textContent='Enviando...'}if(status)status.textContent='Enviando arquivo...';const path=`resources/${safeName(lessonId)}/extra-${Date.now()}-${safeName(file.name)}`,url=await uploadToLessonStorage(path,file);const plan=findPlan(lessonId),user=getUser(),resource={id:uid('res'),title,label:title,type:document.getElementById('lpExtraType')?.value||'PDF',category:'extra',source:canManageOfficial()?'purple':'team',status:canManageOfficial()?'approved':'pending',description:document.getElementById('lpExtraDescription')?.value.trim()||'',whenToUse:document.getElementById('lpExtraWhen')?.value.trim()||'',url,link:url,storagePath:path,fileName:file.name,fileSize:file.size,mimeType:file.type||'application/pdf',uploadedAt:new Date().toISOString(),contributorId:user?.id||'',contributorName:user?.name||'Equipe Purple',stageKey:'general'};plan.resources.unshift(resource);saveHistory(plan,'Adicionou atividade extra',`${resource.contributorName} adicionou ${title}.`);await savePlan();window.App.closeModal();setLessonTab('extras');toast(resource.status==='pending'?'Atividade enviada para revisão.':'Atividade extra salva.')}catch(error){if(status)status.textContent=`Erro: ${error.message||error}`;toast(`Não foi possível salvar atividade: ${error.message||error}`)}finally{if(button){button.disabled=false;button.textContent='Salvar atividade'}}}
  function openMediaLinkEditor(lessonId){if(!canContribute())return toast('Contribuição não autorizada.');window.modal?.(`<div class="modal-head"><div><span class="eyebrow">Links & Mídia</span><h3>Adicionar recurso externo</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="lp-upload-modal"><div class="form-grid cols-2"><div class="field"><label>Título</label><input id="lpMediaTitle" placeholder="Ex.: Past Simple Review"/></div><div class="field"><label>Tipo</label><select id="lpMediaType">${MEDIA_TYPES.map(type=>`<option>${escape(type)}</option>`).join('')}</select></div><div class="field span-2"><label>URL</label><input id="lpMediaUrl" placeholder="https://..."/></div></div><div class="field"><label>Descrição curta</label><textarea id="lpMediaDescription"></textarea></div><div class="field"><label>Quando usar</label><input id="lpMediaWhen" placeholder="Ex.: Review • 5-10 min"/></div><small id="lpMediaStatus">O link será validado antes de salvar.</small></div><div class="section-actions"><button class="btn ghost" onclick="window.App.closeModal()">Cancelar</button><button id="lpMediaSave" class="btn primary" onclick="PurpleLessonPlans.saveMediaLink('${escape(lessonId)}')">Salvar link</button></div>`,true)}
  async function saveMediaLink(lessonId){const button=document.getElementById('lpMediaSave'),status=document.getElementById('lpMediaStatus'),url=document.getElementById('lpMediaUrl')?.value.trim()||'',title=document.getElementById('lpMediaTitle')?.value.trim()||'Recurso externo';try{if(!title)return toast('Informe o título.');if(!validUrl(url))throw new Error('Informe uma URL http/https válida.');if(button){button.disabled=true;button.textContent='Salvando...'}const plan=findPlan(lessonId),user=getUser(),resource={id:uid('res'),title,label:title,type:document.getElementById('lpMediaType')?.value||'Site',category:'media',source:canManageOfficial()?'purple':'team',status:canManageOfficial()?'approved':'pending',description:document.getElementById('lpMediaDescription')?.value.trim()||'',whenToUse:document.getElementById('lpMediaWhen')?.value.trim()||'',url,link:url,uploadedAt:new Date().toISOString(),contributorId:user?.id||'',contributorName:user?.name||'Equipe Purple',stageKey:'general'};plan.resources.unshift(resource);saveHistory(plan,'Adicionou link/mídia',`${resource.contributorName} adicionou ${title}.`);await savePlan();window.App.closeModal();setLessonTab('media');toast(resource.status==='pending'?'Link enviado para revisão.':'Link salvo.')}catch(error){if(status)status.textContent=`Erro: ${error.message||error}`;toast(`Não foi possível salvar link: ${error.message||error}`)}finally{if(button){button.disabled=false;button.textContent='Salvar link'}}}
  function findResource(id){for(const plan of Object.values(ensureWorkspace().lessonPlans)){const resource=(plan.resources||[]).find(item=>item.id===id);if(resource)return {plan,resource}}return {plan:null,resource:null}}
  async function openResourcePdf(id){const {plan,resource}=findResource(id);if(!resource?.storagePath)return toast('Arquivo não encontrado.');await openPdfViewer({kind:'resource',lessonId:plan.lessonId,resourceId:id,title:resource.title,storagePath:resource.storagePath,fileName:resource.fileName,page:1,printable:true})}
  async function printResourcePdf(id){const {resource}=findResource(id);if(!resource?.storagePath)return toast('Arquivo não encontrado.');try{const url=await signedStorageUrl(resource.storagePath);const popup=window.open(url,'_blank','noopener,noreferrer');setTimeout(()=>popup?.print?.(),900)}catch(error){toast(`Não foi possível imprimir: ${error.message||error}`)}}
  async function approveResource(id){if(!canManageOfficial())return toast('Aprovação restrita à coordenação.');const {plan,resource}=findResource(id);if(!resource)return toast('Recurso não encontrado.');resource.status='approved';resource.approvedAt=new Date().toISOString();resource.approvedBy=getUser()?.id||'';saveHistory(plan,'Aprovou contribuição',`${userLabel(getUser()?.id)} aprovou ${resource.title}.`);await savePlan();window.App.renderPage();toast('Contribuição aprovada.')}
  function renderMeetingOverview(plan,m){const relations=(plan.unitRelations||[]).map(rel=>{const unit=(m.course?.units||[]).find(item=>item.id===rel.unitId);return `${unit?.title||rel.unitId} ${unit?.theme?`— ${unit.theme}`:''} • pp.${rel.pages}`}).join(' | ');return `<section class="panel lp-meeting-overview"><div class="panel-head"><div><span class="eyebrow">Currículo operacional</span><h3>${escape(plan.meetingNumber?`Class Meeting ${plan.meetingNumber}`:'Lesson Plan')}</h3></div><b>${escape(plan.bookPages||m.lesson.bookPages||'')}</b></div><div class="lp-summary-grid"><div><span>Unit(s)</span><p>${escape(relations||m.unit.title)}</p></div><div><span>Objetivo</span><p>${escape(plan.communicativeObjective)}</p></div><div><span>Teacher Preparation</span><p>${escape(plan.teacherPreparation||'—')}</p></div><div><span>Expected Outcome</span><p>${escape(plan.expectedOutcome||'—')}</p></div><div><span>Ready / Mastery</span><p>${escape(plan.readyForNext||plan.unitMastery||'—')}</p></div><div><span>R.A.P.I.D.</span><p>${escape(plan.rapidSummary||'—')}</p></div></div></section>`}
  function renderTeacherQuickView(plan){const current=LESSON_STAGES.map(stage=>({stage,data:plan.stages?.[stage.key]||{}})).find(item=>item.data.duration)||{stage:LESSON_STAGES[0],data:{}};return `<section class="panel lp-teacher-quick"><div><span class="eyebrow">Teacher Quick View</span><h3>${escape(current.stage.label)} • ${fmtNumber(current.data.duration||0)} min</h3><p>${escape(current.data.instructions||current.data.activity||'Abra o Lesson Flow para conduzir a aula.')}</p></div><div><b>Páginas</b><span>${escape(current.data.studentBookPages||current.data.pages||plan.bookPages||'—')}</span></div><div><b>Interação</b><span>${escape(current.data.interaction||'—')}</span></div><div><b>Próximo passo</b><span>${escape(current.data.successCriteria||plan.readyForNext||'Monitorar evidência comunicativa.')}</span></div></section>`}
  function renderLearningArcs(plan){if(!plan.meetingArcs?.length)return '';return `<section class="panel lp-learning-arcs"><div class="panel-head"><div><span class="eyebrow">Transition Learning Arcs</span><h3>Meeting 05: Unit 02 -> Unit 03</h3></div></div>${plan.meetingArcs.map(arc=>`<article><div><h4>${escape(arc.title)}</h4><span>${fmtNumber(arc.duration)} min • pp.${escape(arc.pages)}</span></div><p>${escape(arc.objective)}</p><ol>${(arc.steps||[]).map(step=>`<li>${escape(step)}</li>`).join('')}</ol></article>`).join('')}</section>`}
  function renderRapidCompact(plan){return `<section class="panel lp-rapid-compact"><div><span class="eyebrow">R.A.P.I.D. Check</span><h3>Metodologia orientando a aula</h3></div><div>${RAPID_PRINCIPLES.map(item=>`<span class="${plan.rapidCheck?.[item.key]?'active':''}"><b>${item.short}</b>${escape(item.label)}</span>`).join('')}</div></section>`}
  function renderLessonFlow(plan,edit){return `<section class="panel lp-flow"><div class="panel-head"><div><span class="eyebrow">Lesson Flow</span><h3>Guia pedagógico digital</h3></div></div>${LESSON_STAGES.map((stage,index)=>renderFlowStage(plan,stage,index+1,edit)).join('')}</section>`}
  function renderFlowStage(plan,stage,index,edit){const data=plan.stages[stage.key]||{};if(edit)return `<article class="lp-flow-stage edit"><h3>${String(index).padStart(2,'0')} ${escape(stage.label)}</h3><div class="form-grid cols-2"><div class="field"><label>Objetivo</label><textarea id="lpEdit-${stage.key}-objective">${escape(data.objective||'')}</textarea></div><div class="field"><label>Atividade</label><textarea id="lpEdit-${stage.key}-activity">${escape(data.activity||'')}</textarea></div><div class="field"><label>Orientação</label><textarea id="lpEdit-${stage.key}-instructions">${escape(data.instructions||'')}</textarea></div><div class="field"><label>Teacher notes</label><textarea id="lpEdit-${stage.key}-observations">${escape(data.observations||'')}</textarea></div></div><div class="form-grid cols-4"><div class="field"><label>Tempo</label><input id="lpEdit-${stage.key}-duration" type="number" value="${escape(data.duration||0)}"/></div><div class="field"><label>Interação</label><input id="lpEdit-${stage.key}-interaction" value="${escape(data.interaction||'')}"/></div><div class="field"><label>Student Book</label><input id="lpEdit-${stage.key}-studentBookPages" value="${escape(data.studentBookPages||'')}"/></div><div class="field"><label>Workbook</label><input id="lpEdit-${stage.key}-workbookPages" value="${escape(data.workbookPages||'')}"/></div></div></article>`;return `<article class="lp-flow-stage"><div class="lp-stage-number">${String(index).padStart(2,'0')}</div><div><div class="lp-stage-title"><h3>${escape(stage.label)}</h3><span>${fmtNumber(data.duration||0)} min</span></div><dl><dt>Objetivo</dt><dd>${escape(data.objective||'—')}</dd><dt>Orientação</dt><dd>${escape(data.instructions||'—')}</dd><dt>Atividade</dt><dd>${escape(data.activity||'—')}</dd><dt>Interação</dt><dd>${escape(data.interaction||'—')}</dd><dt>Páginas</dt><dd>Student Book ${escape(data.studentBookPages||pagesFrom(data.pages,'SB')||'—')} • Workbook ${escape(data.workbookPages||pagesFrom(data.pages,'WB')||'—')} ${(data.studentBookPages||data.pages)?`<button class="link-button" onclick="PurpleLessonPlans.openStageInBook('${escape(plan.lessonId)}','${escape(stage.key)}')">Abrir no livro</button>`:''}</dd><dt>Recursos</dt><dd>${escape((data.resources||[]).join(' • ')||'—')}</dd><dt>Teacher notes</dt><dd>${escape(data.observations||'—')}</dd></dl></div></article>`}
  function renderResources(plan){return `<section class="panel lp-resources"><div class="panel-head"><div><span class="eyebrow">Recursos da aula</span><h3>Materiais, jogos, vídeos e links</h3></div>${can('lesson_plans.edit')?`<button class="btn primary small" onclick="PurpleLessonPlans.openResourceEditor('${escape(plan.lessonId)}')">+ Adicionar recurso</button>`:''}</div><div class="lp-resource-grid">${(plan.resources||[]).map(renderResourceCard).join('')||'<p class="muted">Nenhum recurso cadastrado.</p>'}</div></section>`}
  function renderResourceCard(resource){const yt=youtubeId(resource.url);return `<article class="lp-resource-card"><div class="lp-resource-icon">${iconForType(resource.type)}</div><div><span>${escape(resource.type)}${resource.stageKey&&resource.stageKey!=='general'?` • ${escape(resource.stageKey)}`:''}</span><h4>${escape(resource.title||resource.label)}</h4><p>${escape(resource.description||'')}</p>${yt?`<img alt="" src="https://img.youtube.com/vi/${escape(yt)}/hqdefault.jpg" loading="lazy"/>`:''}<button class="btn soft small lp-resource-action" onclick="PurpleLessonPlans.openResource('${escape(resource.id)}')">${escape(resourceActionLabel(resource.type))}</button></div></article>`}
  function renderCollectiveContribution(plan,cycle){const rows=ensureWorkspace().contributions.filter(item=>item.lessonId===plan.lessonId);return `<section class="panel lp-collective"><div><span class="eyebrow">Contribuição coletiva</span><h3>${fmtNumber(new Set(rows.map(item=>item.assigneeId)).size)} colaboradores</h3><p>Última atualização ${fmtDateTime(rows[0]?.updatedAt||plan.history?.[0]?.at||'')}</p></div><div class="section-actions"><button class="btn ghost small" onclick="window.App.go('lesson-contributions')">Contribuir</button><button class="btn soft small" onclick="PurpleLessonPlans.openHistory('${escape(plan.lessonId)}')">Ver histórico</button>${can('lesson_plans.cycles.manage')?`<button class="btn ghost small" onclick="PurpleLessonPlans.openCycleEditor('${escape(cycle?.id||'')}')">Gerenciar ciclo</button>`:''}</div></section>`}
  function renderHistory(plan){return `<section class="panel lp-history"><div class="panel-head"><div><span class="eyebrow">Histórico</span><h3>Versionamento e evolução</h3></div></div><div class="timeline">${(plan.history||[]).slice(0,5).map(item=>`<div class="timeline-item"><b>${escape(item.action)}</b><p>${escape(item.detail)}</p><time>${fmtDateTime(item.at)} • ${escape(item.actor)}</time></div>`).join('')}</div></section>`}
  function renderBookContext(course,unit){return `<section class="panel lp-book-side">${renderCover(course,'mini')}<div><span class="eyebrow">Livro digital</span><h3>${escape(course.name)}</h3><p>${course.pdfUrl||course.pdfStoragePath?'PDF associado ao cadastro.':'PDF real ainda não cadastrado. Viewer disponível quando a coordenação associar arquivo seguro.'}</p><button class="btn primary small" onclick="PurpleLessonPlans.openBookViewer('${escape(course.id)}','${escape(unit.studentBookPages||1)}')">Abrir livro</button></div></section>`}
