  function renderManagement(){return `<div class="page lesson-page lp-library-shell">${renderLessonNav('management')}<section class="lp-management-hero"><div><span class="eyebrow">Gestão da biblioteca</span><h1>Capas, PDFs e acervo ficam aqui.</h1><p>Use esta área para manter a biblioteca visual da Purple organizada. Ciclos, contribuições e histórico continuam preservados nos dados, mas não aparecem mais como painel principal.</p></div></section>${renderBookAssetManager()}</div>`}

  function contributionRows(){const teacherMode=getUser()?.role==='teacher';return ensureWorkspace().contributions.filter(item=>!teacherMode||item.assigneeId===getUser()?.id).map(item=>{const meta=findLessonMeta(item.lessonId),cycle=findCycle(item.cycleId);return {...item,meta,cycle,stageLabel:LESSON_STAGES.find(stage=>stage.key===item.stageKey)?.label||item.stageKey}})}
