  function previewCoverFit(prefix,selector){const url=document.getElementById(`${prefix}CoverUrl`)?.value.trim()||'',x=Number(document.getElementById(`${prefix}CoverX`)?.value||50),y=Number(document.getElementById(`${prefix}CoverY`)?.value||50),zoom=Number(document.getElementById(`${prefix}CoverZoom`)?.value||100),target=document.querySelector(`${selector} .lp-cover`);if(!target)return;if(url){target.classList.remove('placeholder');target.innerHTML='';target.style.backgroundImage=`url('${url.replace(/'/g,'%27')}')`;target.style.backgroundPosition=`${x}% ${y}%`;target.style.backgroundSize=`${zoom}% auto`}else{target.removeAttribute('style')}}
  function nextCollectionId(name=''){const existing=new Set(ensureWorkspace().collections.map(collection=>collection.id));let base=safeName(name||'nova-colecao')||'nova-colecao',n=1,id=base;while(existing.has(id))id=`${base}-${++n}`;return id}
