  function openCollectionEditor(collectionId=''){if(!canManageOfficial())return toast('Cadastro de coleção restrito à coordenação.');const editing=Boolean(collectionId),collection=editing?findCollection(collectionId):editableCollectionDraft(),fit=coverFit(collection);window.modal?.(`<div class="modal-head"><div><span class="eyebrow">${editing?'Gerenciar coleção':'Nova coleção'}</span><h3>${escape(collection.name)}</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="lp-book-editor lp-collection-editor"><div class="lp-book-editor-preview"><div id="lpCollectionCoverPreview">${renderCover(collection,'collection-large')}</div><small id="lpCollectionUploadStatus">${collection.coverUrl||collection.coverStoragePath?'Capa real cadastrada':'Placeholder premium até associar a capa da coleção'}</small><div class="lp-cover-controls"><label>Zoom da capa <input id="lpCollectionCoverZoom" type="range" min="80" max="180" value="${fit.zoom}" oninput="PurpleLessonPlans.previewCollectionCoverFit()"/></label><label>Horizontal <input id="lpCollectionCoverX" type="range" min="0" max="100" value="${fit.x}" oninput="PurpleLessonPlans.previewCollectionCoverFit()"/></label><label>Vertical <input id="lpCollectionCoverY" type="range" min="0" max="100" value="${fit.y}" oninput="PurpleLessonPlans.previewCollectionCoverFit()"/></label></div></div><div class="lp-book-editor-form"><input id="lpCollectionDraftId" type="hidden" value="${escape(collection.id)}"/><div class="form-grid cols-2"><div class="field"><label>Nome</label><input id="lpCollectionName" value="${escape(collection.name)}"/></div><div class="field"><label>Status</label><select id="lpCollectionStatus"><option value="active" ${collection.status==='active'?'selected':''}>Ativa</option><option value="draft" ${collection.status==='draft'?'selected':''}>Em preparo</option><option value="archived" ${collection.status==='archived'?'selected':''}>Arquivada</option></select></div><div class="field"><label>Ordem</label><input id="lpCollectionOrder" type="number" min="1" value="${escape(collection.order||1)}"/></div></div><input id="lpCollectionCoverStoragePath" type="hidden" value="${escape(collection.coverStoragePath||'')}"/><div class="field"><label>URL segura da capa da coleção</label><input id="lpCollectionCoverUrl" value="${escape(collection.coverUrl||'')}" oninput="PurpleLessonPlans.previewCollectionCoverFit()" placeholder="https://.../super-kids-cover.png"/><small>Use uma capa real ou uma composição oficial. Não criamos capa falsa como se fosse oficial.</small></div><div class="lp-upload-drop"><b>Subir capa da coleção</b><span>Envia para o Supabase Storage em <code>${escape(storageBucket())}</code>. Depois ajuste o enquadramento e salve.</span><div class="lp-file-actions"><label><input id="lpCollectionCoverFile" type="file" accept="image/*" onchange="PurpleLessonPlans.uploadCollectionCover(document.getElementById('lpCollectionDraftId')?.value||'${escape(collection.id)}')"/>Subir capa</label></div></div><div class="field"><label>Descrição</label><textarea id="lpCollectionDescription">${escape(collection.description||'')}</textarea></div></div></div><div class="section-actions"><button class="btn ghost" onclick="window.App.closeModal()">Cancelar</button>${editing?`<button class="btn soft" onclick="PurpleLessonPlans.openCollection('${escape(collectionId)}')">Ver coleção</button>`:''}<button id="lpCollectionSaveButton" class="btn primary" onclick="PurpleLessonPlans.saveCollectionEditor('${escape(collectionId)}')">${editing?'Salvar coleção':'Criar coleção'}</button></div>`,true)}
  function previewCollectionCoverFit(){previewCoverFit('lpCollection','#lpCollectionCoverPreview')}
  async function uploadCollectionCover(collectionId){if(!canManageOfficial())return toast('Cadastro de coleção restrito à coordenação.');const input=document.getElementById('lpCollectionCoverFile'),file=input?.files?.[0],status=document.getElementById('lpCollectionUploadStatus');if(!file)return;try{const ext=assertFile(file,{kind:'capa da coleção',types:['image/png','image/jpeg','image/webp'],extensions:['png','jpg','jpeg','webp'],maxSize:12*1024*1024});if(status)status.textContent=`Enviando ${file.name}...`;document.getElementById('lpCollectionCoverUrl').value=URL.createObjectURL(file);previewCollectionCoverFit();const path=`collections/${safeName(collectionId)}/cover-${Date.now()}.${ext}`,url=await uploadToLessonStorage(path,file);document.getElementById('lpCollectionCoverUrl').value=url;document.getElementById('lpCollectionCoverStoragePath').value=path;previewCollectionCoverFit();if(status)status.textContent='Capa enviada. Ajuste o enquadramento e salve.';toast('Capa da coleção enviada.')}catch(error){if(status)status.textContent=`Upload não concluído: ${error.message||error}`;toast(`Upload não concluído: ${error.message||error}`)}}
  async function saveCollectionEditor(collectionId=''){if(!canManageOfficial())return toast('Cadastro de coleção restrito à coordenação.');const button=document.getElementById('lpCollectionSaveButton'),status=document.getElementById('lpCollectionUploadStatus'),w=ensureWorkspace(),existing=collectionId?w.collections.find(collection=>collection.id===collectionId):null,before=existing?JSON.parse(JSON.stringify(existing)):null;let collection=existing,isNew=false;try{if(button){button.disabled=true;button.textContent='Salvando...'}if(!collection){isNew=true;collection={id:document.getElementById('lpCollectionDraftId')?.value.trim()||nextCollectionId(document.getElementById('lpCollectionName')?.value.trim()),bookIds:[],createdAt:new Date().toISOString()};w.collections.push(collection)}collection.name=document.getElementById('lpCollectionName')?.value.trim()||collection.name||'Nova coleção';collection.status=document.getElementById('lpCollectionStatus')?.value||collection.status||'draft';collection.order=Number(document.getElementById('lpCollectionOrder')?.value||collection.order||w.collections.length);collection.coverUrl=document.getElementById('lpCollectionCoverUrl')?.value.trim()||'';collection.coverStoragePath=document.getElementById('lpCollectionCoverStoragePath')?.value.trim()||collection.coverStoragePath||'';collection.coverUrlSignedAt=collection.coverStoragePath?new Date().toISOString():'';collection.coverZoom=Number(document.getElementById('lpCollectionCoverZoom')?.value||100);collection.coverPositionX=Number(document.getElementById('lpCollectionCoverX')?.value||50);collection.coverPositionY=Number(document.getElementById('lpCollectionCoverY')?.value||50);collection.description=document.getElementById('lpCollectionDescription')?.value.trim()||'';collection.bookIds=collection.bookIds||[];collection.updatedAt=new Date().toISOString();if(status)status.textContent='Salvando coleção...';await savePlan();window.App.closeModal();openCollection(collection.id);toast(isNew?'Coleção criada.':'Coleção atualizada.')}catch(error){if(isNew)w.collections=w.collections.filter(item=>item!==collection);else if(before){Object.keys(collection).forEach(key=>delete collection[key]);Object.assign(collection,before)}console.error('Lesson Plans — erro ao salvar coleção:',error);if(status)status.textContent=`Erro ao salvar: ${error.message||error}`;toast(`Erro ao salvar coleção: ${error.message||error}`)}finally{if(button){button.disabled=false;button.textContent='Salvar coleção'}}}
  async function deleteCollection(collectionId){if(!canManageOfficial())return toast('Exclusão restrita à coordenação.');const w=ensureWorkspace(),collection=w.collections.find(item=>item.id===collectionId);if(!collection)return toast('Coleção não encontrada.');const books=collectionBooks(collection);if(books.length)return toast('Para excluir a coleção, remova ou mova os livros/programas primeiro.');if(!window.confirm?.(`Excluir a coleção ${collection.name}?`))return;w.collections=w.collections.filter(item=>item.id!==collectionId);await savePlan();openLibrary();toast('Coleção excluída.')}
