  function unitEditorMarkup(courseId,unitId=''){const course=findCourse(courseId),u=unitId?findUnit(courseId,unitId):editableUnitDraft(course),editing=Boolean(unitId);return `<div class="modal-head"><div><span class="eyebrow">${editing?'Editar unidade':'Nova unidade'}</span><h3>${escape(editing?`${u.title} — ${u.theme||''}`:`${course.name} • nova unidade`)}</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="lp-unit-editor"><div class="alert blue"><div class="alert-icon">i</div><div><b>O PDF lançado é o plano principal da unidade.</b><span>Use estes campos para organizar título, subtítulo, páginas, busca e contexto. A estrutura pedagógica antiga continua opcional.</span></div></div><div class="form-grid cols-2"><div class="field"><label>Título da unidade</label><input id="lpUnitTitle" value="${escape(u.title||'')}"/></div><div class="field"><label>Tema / subtítulo curto</label><input id="lpUnitTheme" value="${escape(u.theme||'')}"/></div><div class="field span-2"><label>Subtítulo exibido no topo</label><textarea id="lpUnitSubtitle">${escape(u.subtitle||u.objective||'')}</textarea></div><div class="field"><label>Páginas Student Book</label><input id="lpUnitStudentBookPages" value="${escape(u.studentBookPages||'')}"/></div><div class="field"><label>Páginas Workbook</label><input id="lpUnitWorkbookPages" value="${escape(u.workbookPages||'')}"/></div><div class="field"><label>Faixa / turma</label><input id="lpUnitAudience" value="${escape(u.audience||'')}"/></div><div class="field"><label>Aulas/meetings</label><input id="lpUnitEstimatedLessons" type="number" min="1" value="${escape(u.estimatedLessons||1)}"/></div></div><details class="lp-legacy-fields"><summary>Campos legados opcionais</summary><p>Preencha apenas se quiser melhorar busca ou manter referência complementar. O professor não depende mais destes campos para usar a unidade.</p><div class="form-grid cols-2"><div class="field"><label>Objetivo comunicativo</label><textarea id="lpUnitObjective">${escape(u.objective||'')}</textarea></div><div class="field"><label>Resultado esperado</label><textarea id="lpUnitExpectedOutcome">${escape(u.expectedOutcome||'')}</textarea></div><div class="field"><label>Conteúdo</label><textarea id="lpUnitContent">${escape(u.content||'')}</textarea></div><div class="field"><label>Notas da coordenação</label><textarea id="lpUnitCoordinatorNotes">${escape(u.coordinatorNotes||'')}</textarea></div><div class="field"><label>Vocabulário</label><input id="lpUnitVocabulary" value="${escape((u.vocabulary||[]).join(', '))}"/></div><div class="field"><label>Gramática</label><input id="lpUnitGrammar" value="${escape((u.grammar||[]).join(', '))}"/></div><div class="field"><label>Skills</label><input id="lpUnitSkills" value="${escape((u.skills||[]).join(', '))}"/></div><div class="field"><label>Recursos</label><input id="lpUnitResources" value="${escape((u.resources||[]).join(', '))}"/></div><div class="field"><label>Pontos de atenção</label><textarea id="lpUnitAttention">${escape((u.attentionPoints||[]).join(', '))}</textarea></div><div class="field"><label>Dificuldades previstas</label><textarea id="lpUnitDifficulties">${escape((u.expectedDifficulties||[]).join(', '))}</textarea></div></div></details></div><div class="section-actions"><button class="btn ghost" onclick="window.App.closeModal()">Cancelar</button>${editing?`<button class="btn soft" onclick="PurpleLessonPlans.openUnit('${escape(courseId)}','${escape(unitId)}')">Ver unidade</button>`:''}<button class="btn primary" onclick="PurpleLessonPlans.saveUnitEditor('${escape(courseId)}','${escape(unitId)}')">${editing?'Salvar unidade':'Criar unidade'}</button></div>`}
  function openUnitEditor(courseId,unitId=''){if(!canManageOfficial())return toast('Unidade restrita à coordenação.');window.modal?.(unitEditorMarkup(courseId,unitId),true)}
