  async function saveUnitEditor(courseId,unitId=''){if(!canManageOfficial())return toast('Unidade restrita à coordenação.');const course=findCourse(courseId),value=id=>document.getElementById(id)?.value;let u=unitId?findUnit(courseId,unitId):null,isNew=false;if(!u){isNew=true;u={...editableUnitDraft(course),id:nextUnitId(course),createdAt:new Date().toISOString()};course.units=course.units||[];course.units.push(u)}Object.assign(u,{title:value('lpUnitTitle')?.trim()||u.title,theme:value('lpUnitTheme')?.trim()||u.theme,subtitle:value('lpUnitSubtitle')?.trim()||'',audience:value('lpUnitAudience')?.trim()||u.audience,studentBookPages:value('lpUnitStudentBookPages')?.trim()||u.studentBookPages,workbookPages:value('lpUnitWorkbookPages')?.trim()||u.workbookPages,estimatedLessons:Number(value('lpUnitEstimatedLessons')||u.estimatedLessons||1),objective:value('lpUnitObjective')?.trim()??u.objective,expectedOutcome:value('lpUnitExpectedOutcome')?.trim()??u.expectedOutcome,content:value('lpUnitContent')?.trim()??u.content,vocabulary:document.getElementById('lpUnitVocabulary')?csv(value('lpUnitVocabulary')):u.vocabulary,grammar:document.getElementById('lpUnitGrammar')?csv(value('lpUnitGrammar')):u.grammar,skills:document.getElementById('lpUnitSkills')?csv(value('lpUnitSkills')):u.skills,resources:document.getElementById('lpUnitResources')?csv(value('lpUnitResources')):u.resources,attentionPoints:document.getElementById('lpUnitAttention')?csv(value('lpUnitAttention')):u.attentionPoints,expectedDifficulties:document.getElementById('lpUnitDifficulties')?csv(value('lpUnitDifficulties')):u.expectedDifficulties,coordinatorNotes:value('lpUnitCoordinatorNotes')?.trim()??u.coordinatorNotes,lessons:u.lessons||[],status:u.status||'draft',updatedAt:new Date().toISOString()});await savePlan();window.App.closeModal();openUnit(courseId,u.id);toast(isNew?'Unidade criada.':'Unidade atualizada.')}
