  async function deleteUnit(courseId,unitId){if(!canManageOfficial())return toast('Exclusão restrita à coordenação.');const course=findCourse(courseId),unit=(course.units||[]).find(item=>item.id===unitId);if(!unit)return toast('Unidade não encontrada.');const lessonIds=(unit.lessons||[]).map(lesson=>lesson.id),lessonText=lessonIds.length?` e ${fmtNumber(lessonIds.length)} lesson(s) vinculada(s)`:'';if(!window.confirm?.(`Excluir ${unit.title} — ${unit.theme||'unidade'}${lessonText}? Essa ação remove vínculos desta unidade da biblioteca.`))return;const w=ensureWorkspace();course.units=(course.units||[]).filter(item=>item.id!==unitId);for(const lessonId of lessonIds)delete w.lessonPlans[lessonId];w.contributions=(w.contributions||[]).filter(item=>!lessonIds.includes(item.lessonId));w.cycles=(w.cycles||[]).map(cycle=>({...cycle,lessonIds:(cycle.lessonIds||[]).filter(id=>!lessonIds.includes(id))})).filter(cycle=>cycle.unitId!==unitId&&(cycle.lessonIds||[]).length);w.publishedFeed=(w.publishedFeed||[]).filter(item=>!lessonIds.includes(item.lessonId));if(w.lastOpened?.unitId===unitId){const firstCourse=w.courses?.[0],firstUnit=firstCourse?.units?.[0],firstLesson=firstUnit?.lessons?.[0];w.lastOpened={courseId:firstCourse?.id||'',unitId:firstUnit?.id||'',lessonId:firstLesson?.id||''}}await savePlan();openCourse(courseId);toast('Unidade excluída.')}
  function openFeedbackModal(lessonId){const p=findPlan(lessonId);window.modal?.(`<div class="modal-head"><div><span class="eyebrow">Feedback pós-aula</span><h3>${escape(p.theme)}</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="field"><label>O que aconteceu em sala?</label><textarea id="lpPostClassFeedback" class="large"></textarea></div><div class="section-actions"><button class="btn ghost" onclick="window.App.closeModal()">Cancelar</button><button class="btn primary" onclick="PurpleLessonPlans.saveFeedback('${escape(lessonId)}')">Salvar feedback</button></div>`,true)}
  async function saveFeedback(lessonId){const p=findPlan(lessonId),note=document.getElementById('lpPostClassFeedback')?.value.trim()||'Feedback pós-aula registrado.';p.postClassFeedback.unshift({id:uid('fb'),at:new Date().toISOString(),actor:userLabel(getUser()?.id),note});saveHistory(p,'Registrou feedback pós-aula',note);bumpPlan(p);await savePlan();window.App.closeModal();window.App.renderPage()}
  function openHistory(lessonId){const p=findPlan(lessonId);window.modal?.(`<div class="modal-head"><div><span class="eyebrow">Histórico</span><h3>${escape(p.theme)}</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="timeline">${(p.history||[]).map(item=>`<div class="timeline-item"><b>${escape(item.action)}</b><p>${escape(item.detail)}</p><time>${fmtDateTime(item.at)} • ${escape(item.actor)}</time></div>`).join('')}</div>`,true)}
  function printPlan(id){const popup=window.open('','_blank');if(!popup)return toast('Não foi possível abrir impressão.');popup.document.write(printDocument(id));popup.document.close();popup.focus();popup.print?.()}
